    agregar("G47-L2-08", CLASE_47, "L2", "Carbones o escobillas del regulador del alternador gastados a menos de 2 mm; hacen contacto intermitente prendiendo y apagando el testigo de batería al superar 3000 rpm.", "TALLER", "alta_revolucion_3000rpm", "carbones_alternador_gastados_2mm|testigo_parpadea_a_3000rpm", "falla_fuga_nocturna", "", "NO", "SI", "Fuga parasita de corriente en reposo (consumo nocturno de bateria)", "L2 escobillas gastadas encienden testigo a altas RPM.")
    agregar("G47-L2-09", CLASE_47, "L2", "Al encender las luces altas y el desempañador térmico el voltaje de carga se desploma de 13.6 V a 11.8 V; con todos los consumidores apagados genera 13.5 V.", "COTIDIANO", "ralenti_consumidores_altos", "voltaje_desploma_13_6_a_11_8v_con_cargas", "falla_borne_sulfatado", "", "NO", "SI", "Bateria descargada o bornes sulfatados", "L2 alternador incapaz de sostener amperaje con consumidores.")
    agregar("G47-L2-10", CLASE_47, "L2", "Polea libre desacopladora del alternador (OAP) totalmente gripada; genera vibración y zumbido metálico en la faja de accesorios que desaparece al retirar la correa.", "TECNICO", "inspeccion_polea_oap_desacopladora", "polea_desacopladora_oap_gripada|vibracion_faja_accesorios", "falla_bomba_agua", "", "NO", "SI", "Falla en termostato o motoventilador de radiador", "L2 polea desacopladora OAP gripada zumba en accesorios.")
