    agregar("G47-L2-13", CLASE_47, "L2", "Estator del alternador con bobinado quemado de color negro carbón y barniz derretido; al medir continuidad entre fase y masa chasis se constata cortocircuito a tierra.", "TALLER", "desarme_banco_estator_quemado", "estator_bobinado_quemado_negro|cortocircuito_fase_a_masa", "falla_arranque", "", "NO", "SI", "Falla en motor de arranque o solenoide defectuoso (clac seco o carbones gastados)", "L2 bobinado de estator quemado en cortocircuito a masa.")
