    # --- L3 (15 casos) ---
    agregar("G47-L3-01", CLASE_47, "L3", "Diagnóstico de sistema de carga con osciloscopio automotriz en bornes de batería con motor a 2000 rpm: se observa señal de tensión rectificada con caída periódica profunda de una cresta trifásica con rizado alterno (AC ripple) de 850 mV pico a pico (tolerancia máxima OEM menor a 150 mV AC). En modo voltímetro DC la tensión promedio se sitúa en 12.85 V con luces bajas encendidas (especificación 13.80 V a 14.40 V). Se desmonta el alternador y se comprueba en banco que dos diodos zener de la rama negativa de la placa rectificadora están en circuito abierto.", "TECNICO", "osciloscopio_2000rpm_ac_ripple_850mv", "ac_ripple_850mv_vs_150mv|tension_dc_12_85v_a_2000rpm|dos_diodos_rama_negativa_abiertos", "falla_bateria_quimica", "", "NO", "SI", "Bateria descargada o bornes sulfatados", "L3 osciloscopio registra ripple de 850 mV AC y 12.85V DC por diodos abiertos.")
    agregar("G47-L3-02", CLASE_47, "L3", "Evaluación de alternador pilotado por PWM (módulo de control LIN / RLO en Ford Ranger): el escáner registra DTC P065B referente a rendimiento del circuito de control del alternador. En flujo de datos en vivo el comando de ciclo de trabajo PWM hacia el regulador marca 78% pero la señal de retroalimentación de carga (Field Monitor / terminal FR) permanece estancada en 0.0% con tensión de red en 11.6 V. Prueba con generador de señales confirma que el regulador electrónico inteligente integrado no responde al bus LIN.", "TECNICO", "scanner_datos_en_vivo_p065b_lin_bus", "dtc_p065b|comando_pwm_78porciento_retorno_cero|tension_red_11_6v|regulador_lin_no_responde", "falla_bateria_12v", "P065B", "NO", "SI", "Bateria descargada o bornes sulfatados", "L3 DTC P065B con falla en comunicación LIN bus de alternador inteligente.")
    agregar("G47-L3-03", CLASE_47, "L3", "Prueba de carga máxima en banco de alternadores con reóstato de potencia a 3000 rpm de rotor: alternador nominal de 120 A entrega únicamente 34 A a 13.2 V antes de que la tensión caiga por debajo de 11.5 V. Análisis térmico con cámara infrarroja constata sobrecalentamiento focalizado a 142°C en el tercio inferior del estator debido a espiras en cortocircuito entre fases (resistencia de fase medida en 0.04 ohmios vs 0.28 ohmios nominales).", "TECNICO", "banco_reostato_entrega_34a_vs_120a", "entrega_34a_vs_120a_nominal|estator_a_142c|resistencia_fase_0_04ohm_vs_0_28ohm", "falla_arrancador", "", "NO", "SI", "Falla en motor de arranque o solenoide defectuoso (clac seco o carbones gastados)", "L3 banco confirma entrega de solo 34A de 120A con fase en corto a 142°C.")
    agregar("G47-L3-04", CLASE_47, "L3", "Hola maestro, tengo un Toyota Yaris. Ayer en la noche mientras manejaba con lluvia y luces altas se me encendió la lucecita de la batería en el tablero. A los 10 minutos la radio se apagó, las luces se pusieron amarillas débiles y el timón se puso como una piedra. Cuando me orillé el motor se apagó solo y no dio arranque. Medí con multímetro con motor encendido antes de morir y marcaba 11.4 V; la batería cargada en casa arranca el auto al toque pero en marcha el voltaje se viene abajo.", "WHATSAPP", "yaris_noche_lluvia_luces_altas", "luz_bateria_en_marcha|direccion_dura_luces_debiles|voltaje_11_4v_en_marcha|bateria_externa_ok", "falla_bateria", "", "NO", "SI", "Bateria descargada o bornes sulfatados", "L3 relato WhatsApp de batería que arranca cargada pero cae a 11.4V rodando.")
    agregar("G47-L3-05", CLASE_47, "L3", "Medición de caída de tensión por el cable de fuerza B+ del alternador a borne positivo de batería bajo carga de 60 A: caída de 0.12 V (normal, especificación menor a 0.25 V) y caída de masa de 0.08 V. Sin embargo la tensión directa en el borne B+ con motor a 1500 rpm registra solo 12.15 V con consumo de campo de 0.1 A en el rotor debido a desgaste de anillos rozantes de cobre con surcos de 1.8 mm y escobillas carbonizadas sin presión de resorte.", "TECNICO", "caida_tension_b_positivo_rotor_gastado", "caida_cable_0_12v_ok|tension_borne_b_12_15v|anillos_rozantes_surcos_1_8mm|corriente_campo_0_1a", "falla_cableado_sulfatado", "", "NO", "SI", "Bateria descargada o bornes sulfatados", "L3 cableado perfecto con 0.12V caída pero alternador genera 12.15V por anillos gastados.")
    agregar("G47-L3-06", CLASE_47, "L3", "Diagnóstico de sobretensión intermitente en Chevrolet Cruze: código DTC P0563 presente por alta tensión en el sistema eléctrico (16.8 V registrados en Freeze Frame a 2400 rpm). El regulador de voltaje electrónico sufrió fuga térmica en el transistor de potencia de excitación manteniéndolo saturado al 100%; la sobretensión recalentó la batería provocando ebullición del ácido y activación de modo de protección de la ECU apagando inyectores.", "TECNICO", "freeze_frame_p0563_sobretension_16_8v", "dtc_p0563|freeze_frame_16_8v_a_2400rpm|transistor_excitacion_saturado_100porciento|bateria_hirviendo", "falla_modulo_motor", "P0563", "NO", "SI", "Bateria descargada o bornes sulfatados", "L3 DTC P0563 con sobretensión de 16.8V y ebullición por transistor saturado.")
    agregar("G47-L3-07", CLASE_47, "L3", "Mi carro ase que la luz del tablero y los faros parpadeen rapido como arbolito de navidad cuando ando de noche. El mecanico le puso el voltimetro y con el carro prendio subia y bajaba de 12 a 15 voltios bien loco. Le bajo el alternador y la placa de diodos taba chamuscada con olor a quemao. La bateria taba buena retiene doce punto seis parada.", "ERROR_ORTOGRAFICO", "luces_parpadean_voltaje_inestable", "luces_parpadean_arbolito_navidad|voltaje_inestable_12_a_15v|placa_diodos_chamuscada|bateria_12_6v_parada", "falla_bateria", "", "NO", "SI", "Bateria descargada o bornes sulfatados", "L3 voltaje oscilante 12-15V con placa chamuscada y ortografía informal.")
    agregar("G47-L3-08", CLASE_47, "L3", "Ensayo en osciloscopio automotriz acoplado a la línea de excitación DF/FR: el alternador emite un zumbido audible de 600 Hz transmitido a los altavoces de la radio que incrementa en frecuencia con la aceleración. La señal muestra una deformación periódica con un semiciclo positivo cortado a cero voltios correspondiente a la destrucción por avalancha de un diodo rectificador principal de 50 A.", "TECNICO", "osciloscopio_zumbido_radio_diodo_destruido", "zumbido_radio_aumenta_con_rpm|semiciclo_cortado_a_cero|diodo_50a_destruido_avalancha", "falla_bateria", "", "NO", "SI", "Bateria descargada o bornes sulfatados", "L3 zumbido en radio con semiciclo cortado confirma diodo rectificador destruido.")
    agregar("G47-L3-09", CLASE_47, "L3", "Prueba de consumo parasitario del alternador en reposo con motor apagado y llave retirada: la pinza amperimétrica de precisión acusa un consumo continuo de 3.85 A que no desciende tras 45 minutos de reposo; al desconectar la tuerca del cable B+ del alternador el consumo del vehículo cae inmediatamente a 28 mA confirmando fuga masiva interna por diodo rectificador en cortocircuito.", "TECNICO", "consumo_reposo_borne_b_positivo_3_85a", "fuga_3_85a_motor_apagado|cae_a_28ma_al_desconectar_b_positivo|diodo_en_corto", "fuga_red_can", "", "NO", "SI", "Fuga parasita de corriente en reposo (consumo nocturno de bateria)", "L3 diodo de alternador en cortocircuito consume 3.85A en reposo.")
    agregar("G47-L3-10", CLASE_47, "L3", "Inspección de polea libre de alternador (OAP / decoupler): el embrague unidireccional interno de rodillos helicoidales se encuentra soldado en ambos sentidos de giro; al desacelerar bruscamente desde 4500 rpm el rotor del alternador transmite latigazos torsionales a la correa de accesorios provocando vibración de 12 mm en el tensor y chillido estridente sin patinamiento de embrague de tracción.", "TALLER", "polea_oap_soldada_latigazos_tensor", "embrague_oap_soldado_dos_sentidos|latigazos_12mm_tensor_accesorios|chillido_al_desacelerar", "falla_embrague_transmision", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L3 polea desacopladora OAP soldada genera latigazos torsionales al desacelerar.")
    agregar("G47-L3-11", CLASE_47, "L3", "Análisis termográfico FLIR de alternador bajo carga de 80 A tras 20 minutos de banco de pruebas: la carcasa posterior alcanza 138°C en el área de la placa rectificadora de diodos mientras la carcasa frontal opera en 62°C (gradiente térmico de 76°C); la soldadura de estaño de dos diodos se encuentra derretida con goteo metálico en el interior de la tapa plástica.", "TECNICO", "termografia_flir_placa_diodos_138c", "temperatura_placa_diodos_138c_vs_62c|gradiente_termico_76c|soldadura_estaño_derretida", "falla_refrigeracion_motor", "", "NO", "SI", "Falla en termostato o motoventilador de radiador", "L3 termografía acusa 138°C en placa de diodos con desoldadura de estaño.")
    agregar("G47-L3-12", CLASE_47, "L3", "Verificación de alternador en vehículo diésel con bomba de vacío de frenos adosada al eje posterior del alternador: el retén de aceite del depresor de vacío se rompió inundando el bobinado del rotor y el colector de delgas con aceite de motor 15W-40 caliente; la mezcla de aceite y polvo de carbón generó un puente conductor entre delgas anulando el campo magnético y dejando la tensión en 12.0 V.", "TALLER", "depresor_vacio_inunda_alternador_aceite", "aceite_depresor_inunda_rotor_delgas|puente_conductor_carbon_aceite|tension_cae_a_12_0v", "falla_servofreno_vacio", "", "NO", "SI", "Falla en servofreno (booster) o linea de vacio", "L3 fuga de aceite de bomba de vacío contamina alternador anulando excitación.")
    agregar("G47-L3-13", CLASE_47, "L3", "Evaluación de bus LIN de alternador en BMW Serie 3 con escáner ISTA: código de error 2E97 almacenado por generador sin comunicación en línea BSD/LIN; el alternador opera en modo de emergencia por defecto suministrando tensión fija de 13.55 V independiente de la demanda eléctrica y el estado de carga de la batería AGM, impidiendo la regeneración en frenada.", "TECNICO", "scanner_ista_codigo_2e97_lin_bsd", "dtc_2e97_bsd_lin|tension_emergencia_fija_13_55v|sin_carga_inteligente_agm", "falla_bateria_agm", "", "NO", "SI", "Bateria descargada o bornes sulfatados", "L3 código 2E97 de comunicación BSD fija tensión en modo degradado 13.55V.")
    agregar("G47-L3-14", CLASE_47, "L3", "Prueba de aislamiento de bobinado de estator con megóhmetro a 500 V DC: resistencia de aislamiento fase-carcasa de 0.08 Megaohmios (especificación mínima superior a 5.0 Megaohmios); en caliente a 85°C el barniz aislante se perfora provocando derivación a tierra que descarga la batería a través del chasis en solo 4 horas de uso.", "TECNICO", "megohmetro_estator_0_08_megaohm", "aislamiento_fase_carcasa_0_08_mohm_vs_5_mohm|perforacion_barniz_85c|derivacion_a_tierra", "falla_fuga_parasita", "", "NO", "SI", "Fuga parasita de corriente en reposo (consumo nocturno de bateria)", "L3 megóhmetro registra 0.08 Mohm de aislamiento en estator perforado.")
    agregar("G47-L3-15", CLASE_47, "L3", "Sustitución de alternador tras fractura mecánica de rodamiento trasero de agujas del rotor: el rotor experimentó descentramiento radial de 1.2 mm rozando físicamente contra los núcleos polares del estator a 3500 rpm con chirrido estridente de 96 dBA y desprendimiento de virutas de hierro que destruyeron las escobillas del regulador.", "TALLER", "rodamiento_rotor_descentrado_roce_estator", "rodamiento_rotor_destruido|descentramiento_1_2mm_roza_estator|virutas_destruyen_escobillas", "falla_correa_distribucion", "", "NO", "SI", "Faja o cadena de distribucion destensada o con salto de punto", "L3 rotor rozando contra estator por rodamiento destruido genera 96 dBA.")

    # =========================================================================
    # CLASE 48: Bateria descargada o bornes sulfatados (40 casos)
