    # --- L1 (10 casos) ---
    agregar("G48-L1-01", CLASE_48, "L1", "Al girar la llave para encender el carro solo hace un tic-tic-tic rápido y el tablero se apaga.", "COTIDIANO", "intento_arranque_tic_tic", "tic_tic_tic_rapido_tablero_se_apaga", "", "", "SI", "NO", "", "L1 tic-tic rápido con apagado de tablero.")
    agregar("G48-L1-02", CLASE_48, "L1", "Hola, hoy quise prender el auto y está completamente muerto, ni la luz del techo prende.", "WHATSAPP", "manana_completamente_muerto", "completamente_muerto_sin_luz_techo", "", "", "SI", "NO", "", "L1 carro muerto sin luces.")
    agregar("G48-L1-03", CLASE_48, "L1", "Veo como un polvo blanco y verdoso reseco acumulado encima de los postes de la batería.", "COTIDIANO", "inspeccion_bornes_polvo", "polvo_blanco_verdoso_postes_bateria", "", "", "SI", "NO", "", "L1 sulfatación visible en bornes.")
    agregar("G48-L1-04", CLASE_48, "L1", "El motor intenta girar pero muy lento y pesado como si le faltara fuerza eléctrica.", "COTIDIANO", "crank_lento_pesado", "motor_gira_lento_pesado_sin_fuerza", "", "", "SI", "NO", "", "L1 crank lento y pesado.")
    agregar("G48-L1-05", CLASE_48, "L1", "Si le pongo cables pasacorriente arranca de una pero al apagarlo ya no tiene fuerza.", "TALLER", "arranque_con_puente", "arranca_con_cables_no_retiene_fuerza", "", "", "SI", "NO", "", "L1 arranca con puente pero no retiene.")
    agregar("G48-L1-06", CLASE_48, "L1", "Buenas, el carro no da arranque y las agujas del velocímetro vibran locas al fondo.", "WHATSAPP", "intento_arranque_agujas", "agujas_vibran_sin_arrancar", "", "", "SI", "NO", "", "L1 reseteo de agujas en intento de arranque.")
    agregar("G48-L1-07", CLASE_48, "L1", "A veces no prende nada y si muevo los cables de la batería con la mano vuelve la corriente.", "COTIDIANO", "mover_cables_bateria", "vuelve_corriente_al_mover_cables", "", "", "SI", "NO", "", "L1 falso contacto en cables de batería.")
    agregar("G48-L1-08", CLASE_48, "L1", "Ayuda ase clac clac clac en el motor y se reinisia el estereo.", "ERROR_ORTOGRAFICO", "reinicio_estereo_clac", "clac_clac_clac_reinisia_estereo", "", "", "SI", "NO", "", "L1 clac rápido con reinicio de estéreo.")
    agregar("G48-L1-09", CLASE_48, "L1", "La batería ya tiene como 4 años y en invierno le cuesta un mundo hacer girar el motor.", "COTIDIANO", "invierno_antiguedad", "bateria_4_anos_cuesta_en_frio", "", "", "SI", "NO", "", "L1 batería vieja con dificultad en frío.")
    agregar("G48-L1-10", CLASE_48, "L1", "Giro el contacto y se escucha un chasquido continuo de relés adentro del tablero.", "COTIDIANO", "contacto_chasquido_reles", "chasquido_continuo_reles_tablero", "", "", "SI", "NO", "", "L1 chasquido de relés por baja tensión.")

    # --- L2 (15 casos) ---
    agregar("G48-L2-01", CLASE_48, "L2", "Voltaje en reposo de la batería de 11.4 V con motor apagado; al dar arranque el voltaje cae en picada a 6.2 V y el motor de arranque apenas gira una vuelta pesada.", "TECNICO", "reposo_y_cranking_caida_6_2v", "reposo_11_4v|caida_en_cranking_a_6_2v|crank_lento_pesado", "falla_motor_arranque", "", "NO", "SI", "Falla en motor de arranque o solenoide defectuoso (clac seco o carbones gastados)", "L2 caída severa a 6.2V en cranking descarta motor de arranque.")
    agregar("G48-L2-02", CLASE_48, "L2", "Bornes positivo y negativo con costra gruesa de sulfato de plomo azulado; al medir con multímetro hay 12.6 V en los postes de plomo pero solo 9.8 V en los terminales de cobre.", "TALLER", "caida_tension_bornes_sulfatados", "costra_sulfato_plomo_bornes|12_6v_en_postes_vs_9_8v_en_terminales", "falla_bateria_interna", "", "NO", "SI", "Alternador defectuoso o placa de diodos quemada", "L2 caída de tensión de 2.8V entre poste y terminal por sulfato.")
    agregar("G48-L2-03", CLASE_48, "L2", "El auto arranca al toque si se le colocan cables pasacorriente desde otro auto; una vez encendido el alternador mantiene 14.2 V estables en marcha.", "COTIDIANO", "puente_arranca_alternador_14_2v", "arranca_con_cables_al_toque|alternador_mantiene_14_2v", "falla_alternador", "", "NO", "SI", "Alternador defectuoso o placa de diodos quemada", "L2 alternador genera 14.2V perfecto descarta alternador.")
    agregar("G48-L2-04", CLASE_48, "L2", "Batería de ácido-plomo con una celda comunicada o en cortocircuito interno; la tensión en vacío se estanca en 10.5 V fijos y no sube aunque se cargue durante 12 horas.", "TECNICO", "celda_cortocircuito_10_5v", "tension_estancada_10_5v|celda_en_cortocircuito_interno|no_carga_12h", "falla_fuga_nocturna", "", "NO", "SI", "Fuga parasita de corriente en reposo (consumo nocturno de bateria)", "L2 celda en corto estancada en 10.5V fijos.")
    agregar("G48-L2-05", CLASE_48, "L2", "Al accionar el arranque se produce un tableteo rápido tipo ametralladora del solenoide porque la tensión se desploma por debajo de 8 V; las luces de cabina se extinguen.", "COTIDIANO", "tableteo_ametralladora_solenoide", "tableteo_rapido_solenoide|tension_desploma_bajo_8v|luces_se_apagan", "falla_solenoide_arranque", "", "NO", "SI", "Falla en motor de arranque o solenoide defectuoso (clac seco o carbones gastados)", "L2 ametralladora por caída bajo 8V descarta solenoide roto.")
    agregar("G48-L2-06", CLASE_48, "L2", "Hola maestro, dejé el auto con las luces de parqueo prendidas por 4 horas y la batería se agotó; empujando en segunda arrancó y el alternador carga a 14.1 V.", "WHATSAPP", "luces_parqueo_4_horas_agotada", "bateria_agotada_por_luces_parqueo|arranca_empujando|alternador_14_1v", "falla_alternador", "", "NO", "SI", "Alternador defectuoso o placa de diodos quemada", "L2 descarga por luces olvidadas con alternador sano a 14.1V.")
    agregar("G48-L2-07", CLASE_48, "L2", "Densímetro de batería acusa densidad de electrolito de 1.12 g/cm3 en los 6 vasos (completamente descargada, valor nominal 1.28 g/cm3); el alternador genera correctamente.", "TECNICO", "densimetro_electrolito_1_12", "densidad_electrolito_1_12_vs_1_28|bateria_descargada_quimicamente", "falla_alternador", "", "NO", "SI", "Alternador defectuoso o placa de diodos quemada", "L2 densímetro marca 1.12 g/cm3 confirmando descarga total de electrolito.")
    agregar("G48-L2-08", CLASE_48, "L2", "Terminal negativo flojo en el poste de batería; al intentar dar arranque la chispa salta en el borne y se corta toda la energía del tablero instantáneamente.", "TALLER", "terminal_negativo_flojo_chispa", "borne_negativo_flojo|chispa_en_borne_corta_energia_tablero", "falla_chapa_contacto", "", "NO", "SI", "Falla en motor de arranque o solenoide defectuoso (clac seco o carbones gastados)", "L2 borne flojo genera chispa y corta energía total.")
    agregar("G48-L2-09", CLASE_48, "L2", "Batería sellada libre de mantenimiento muestra el visor óptico (ojo mágico) de color negro opaco indicando necesidad de recarga urgente; en reposo marca 11.7 V.", "COTIDIANO", "ojo_magico_negro_11_7v", "ojo_magico_negro_necesita_recarga|tension_reposo_11_7v", "falla_fuga_parasita", "", "NO", "SI", "Fuga parasita de corriente en reposo (consumo nocturno de bateria)", "L2 ojo mágico en negro y 11.7V confirman batería descargada.")
    agregar("G48-L2-10", CLASE_48, "L2", "Comprobador digital de baterías por conductancia arroja resultado 'Reemplazar Batería' con State of Health (SOH) de 22% y resistencia interna de 28 miliohmios (nominal 4.5 mohm).", "TECNICO", "conductancia_soh_22_porciento", "analizador_conductancia_soh_22porciento|resistencia_interna_28mohm_vs_4_5mohm", "falla_motor_arranque", "", "NO", "SI", "Falla en motor de arranque o solenoide defectuoso (clac seco o carbones gastados)", "L2 analizador de conductancia determina SOH en 22% por sulfatación.")
    agregar("G48-L2-11", CLASE_48, "L2", "Buenas tardes, el carro arranca bien si lo uso seguido cada hora, pero si lo dejo parado 4 horas la batería pierde fuerza y gira pesado; no hay consumo parásito.", "WHATSAPP", "autodescarga_interna_4_horas", "pierde_fuerza_en_4_horas|crank_pesado_lento", "fuga_parasita_nocturna", "", "NO", "SI", "Fuga parasita de corriente en reposo (consumo nocturno de bateria)", "L2 autodescarga química interna en 4 horas sin fuga parásita.")
    agregar("G48-L2-12", CLASE_48, "L2", "Nivel de agua destilada y electrolito por debajo de las placas de plomo en 3 vasos; las placas superiores se secaron y se sulfataron irreversiblemente con plomo blanco.", "TALLER", "placas_secas_sulfatadas_blanco", "electrolito_bajo_placas_secas|placas_sulfatadas_en_blanco", "falla_alternador", "", "NO", "SI", "Alternador defectuoso o placa de diodos quemada", "L2 placas de plomo secas y sulfatadas por falta de agua.")
    agregar("G48-L2-13", CLASE_48, "L2", "La radio pierde las memorias FM y el reloj se resetea a 12:00 cada vez que se da arranque debido al desplome de tensión a 7 V provocado por batería agotada.", "COTIDIANO", "reinicio_reloj_radio_al_arrancar", "reloj_resetea_12_00_en_arranque|caida_de_tension_a_7v", "falla_motor_arranque", "", "NO", "SI", "Falla en motor de arranque o solenoide defectuoso (clac seco o carbones gastados)", "L2 reseteo de reloj al arrancar por caída a 7V de batería.")
    agregar("G48-L2-14", CLASE_48, "L2", "Batería AGM de 70 Ah con 5 años de servicio; la corriente de arranque en frío medida es de 180 A CCA frente a los 680 A CCA estipulados en la etiqueta.", "TECNICO", "bateria_agm_180cca_vs_680cca", "capacidad_arranque_180cca_vs_680cca|bateria_agm_agotada_5_anos", "falla_alternador", "", "NO", "SI", "Alternador defectuoso o placa de diodos quemada", "L2 batería AGM entrega solo 180 CCA de 680 CCA nominales.")
    agregar("G48-L2-15", CLASE_48, "L2", "Bornes con apriete cónico suelto; al aplicar fuerza con la mano el terminal gira sobre el poste impidiendo que pasen los 150 A requeridos por el motor de arranque.", "TALLER", "borne_gira_suelto_conico", "borne_gira_con_la_mano|mal_contacto_conico_postes", "falla_solenoide", "", "NO", "SI", "Falla en motor de arranque o solenoide defectuoso (clac seco o carbones gastados)", "L2 borne suelto que gira a mano impide paso de alta corriente.")

    # --- L3 (15 casos) ---
    agregar("G48-L3-01", CLASE_48, "L3", "Evaluación de batería plomo-ácido de 12 V 60 Ah con probador de descarga con resistencia de carbón (carbon pile load tester): en circuito abierto tras 4 horas de reposo la batería registra 12.10 V (50% de carga). Al aplicar una corriente de descarga de 300 A (la mitad del CCA nominal de 600 A) durante 15 segundos la tensión cae bruscamente a 7.40 V (especificación mínima a 20°C debe superar los 9.60 V) con ebullición violenta en el tercer vaso. El alternador en ralentí entrega 14.25 V estables con 25 A de salida descartando falla de carga.", "TECNICO", "carbon_pile_300a_15s_cae_a_7_40v", "carbon_pile_300a_cae_a_7_40v_vs_9_60v|ebullicion_tercer_vaso|alternador_estable_14_25v", "falla_alternador", "", "NO", "SI", "Alternador defectuoso o placa de diodos quemada", "L3 carbon pile tester acusa 7.40V bajo 300A con alternador sano a 14.25V.")
    agregar("G48-L3-02", CLASE_48, "L3", "Diagnóstico de caída de tensión en conexiones de batería (Volt Drop Testing) durante la fase de cranking: se colocó multímetro digital entre el poste central de plomo de la batería y el borne terminal de bronce positivo registrando una caída de tensión de 3.45 V al accionar la llave (tolerancia máxima de conexión 0.20 V). La superficie de contacto interna presentaba pasivación y sulfatación microscópica de sulfato de plomo aislante; tras limpiar los postes con cepillo de cerdas de acero y aplicar grasa dieléctrica la caída bajó a 0.04 V y el motor arrancó en 1.1 segundos.", "TECNICO", "volt_drop_bornes_3_45v_vs_0_20v", "caida_tension_borne_poste_3_45v_vs_0_20v|sulfatacion_aislante_limpieza|caida_baja_a_0_04v", "falla_motor_arranque", "", "NO", "SI", "Falla en motor de arranque o solenoide defectuoso (clac seco o carbones gastados)", "L3 caída de tensión de 3.45V entre poste y borne por sulfatación aislante.")
    agregar("G48-L3-03", CLASE_48, "L3", "Análisis electroquímico con refractómetro óptico de compensación automática de temperatura (ATC): gravedad específica del electrolito en los 6 vasos: vaso 1: 1.115 g/cm3, vaso 2: 1.118 g/cm3, vaso 3: 1.110 g/cm3, vaso 4: 1.265 g/cm3, vaso 5: 1.112 g/cm3, vaso 6: 1.114 g/cm3; desequilibrio grave de gravedad específica con estratificación ácida irreversible. La batería no es capaz de suministrar más de 90 A sin colapsar por debajo de 8 V.", "TECNICO", "refractometro_atc_densidad_1_110", "densidad_electrolito_1_110_estratificacion_acida|desequilibrio_entre_vasos|colapso_bajo_8v", "falla_fuga_parasita", "", "NO", "SI", "Fuga parasita de corriente en reposo (consumo nocturno de bateria)", "L3 refractómetro acusa estratificación ácida a 1.110 g/cm3 colapsando bajo 8V.")
    agregar("G48-L3-04", CLASE_48, "L3", "Hola maestro, tengo un Nissan Tiida. En la mañana al darle al arranque el tablero hace tac-tac-tac rápido como una metralleta, las luces de advertencia parpadean y el motor ni gira. Vino un amigo con cables y puenteamos desde su auto y prendió al segundo intento suavecito. Con el auto prendido medimos el alternador con tester y da 14.15 V parejito, pero apago el carro y la batería en 5 minutos ya marca 10.8 V y no vuelve a prender.", "WHATSAPP", "tiida_tac_tac_metralleta_puente_ok", "metralleta_tac_tac_tablero_parpadea|arranca_con_puente_al_segundo|alternador_14_15v|bateria_cae_a_10_8v", "falla_alternador", "", "NO", "SI", "Alternador defectuoso o placa de diodos quemada", "L3 relato WhatsApp de metralleta que arranca con puente con alternador sano a 14.15V.")
    agregar("G48-L3-05", CLASE_48, "L3", "Medición de corriente de cranking con pinza amperimétrica True RMS y osciloscopio: al activar el arranque la corriente inicial inrush alcanza solo 140 A (nominal 450 A para motor 2.0L) mientras la tensión en bornes cae a 5.8 V debido a que la resistencia interna de la batería aumentó a 42 miliohmios por sulfatación dura de placas (plomo sulfatado cristalizado blanco no reactivo).", "TECNICO", "pinza_amperimetrica_inrush_140a_vs_450a", "corriente_inrush_140a_vs_450a|tension_cae_a_5_8v|resistencia_interna_42mohm|sulfatacion_cristalizada", "falla_motor_arranque", "", "NO", "SI", "Falla en motor de arranque o solenoide defectuoso (clac seco o carbones gastados)", "L3 corriente inrush limitada a 140A por resistencia interna de 42 mohm.")
    agregar("G48-L3-06", CLASE_48, "L3", "Comprobación de batería AGM con analizador de impedancia Midtronics: State of Charge (SOC) en 45%, State of Health (SOH) en 18%, capacidad CCA residual de 160 A (etiqueta 800 A CCA EN). El calculador de gestión de energía IBS (Intelligent Battery Sensor) montado en el borne negativo registra DTC 299B referente a batería profundamente descargada con degradación irrecuperable por ciclos térmicos superiores a 60°C en vano motor.", "TECNICO", "midtronics_soh_18porciento_dtc_299b", "midtronics_soh_18porciento|cca_160a_vs_800a|sensor_ibs_dtc_299b|bateria_profundamente_descargada", "falla_alternador_lin", "", "NO", "SI", "Alternador defectuoso o placa de diodos quemada", "L3 Midtronics mide 18% SOH con sensor IBS reportando degradación irreversible.")
    agregar("G48-L3-07", CLASE_48, "L3", "Mi carro ase un chasquido continuo en los reles del tablero cuando jiro la llave y se bajan los seguros solos. Los bornes de la bateria tenian un cerro de polvo verde y blanco que parecia salitre. Cuando le pase corriente con cables gruesos de camion prendio al toque. El alternador bota catorce punto dos voltios con el carro encendio.", "ERROR_ORTOGRAFICO", "polvo_verde_blanco_salitre_cables", "chasquido_reles_tablero|bornes_polvo_verde_blanco_salitre|arranca_con_cables|alternador_14_2v", "falla_alternador", "", "NO", "SI", "Alternador defectuoso o placa de diodos quemada", "L3 sulfatación salitrosa con alternador a 14.2V y ortografía informal.")
    agregar("G48-L3-08", CLASE_48, "L3", "Prueba de autodescarga electroquímica en banco: batería desconectada físicamente del vehículo en estante de taller a 22°C ambiente pierde 0.35 V diarios (de 12.60 V a 11.20 V en 4 días) sin ninguna carga conectada debido a sedimentación de lodos de dióxido de plomo en el fondo de las celdas que tocan los separadores microporosos generando micro-cortocircuitos internos.", "TECNICO", "autodescarga_banco_0_35v_diarios_lodos", "autodescarga_0_35v_diarios_en_banco|sedimentacion_lodos_plomo|separadores_perforados", "falla_fuga_parasita", "", "NO", "SI", "Fuga parasita de corriente en reposo (consumo nocturno de bateria)", "L3 autodescarga de 0.35 V/día en banco desconectado por sedimentación de lodos.")
    agregar("G48-L3-09", CLASE_48, "L3", "Medición de caída de tensión en masa de chasis (Ground Voltage Drop Test): al aplicar arranque el voltímetro entre borne negativo de batería y bloque motor marca 0.08 V (excelente conexión de masa de motor), pero entre borne negativo y la chapa del borne registra 2.90 V por corrosión interna entre el cable de cobre prensado y el terminal de plomo.", "TECNICO", "ground_drop_test_borne_a_cable_2_90v", "caida_borne_negativo_a_cable_2_90v_vs_0_05v|masa_bloque_0_08v_ok|corrosion_cobre_plomo", "falla_motor_arranque", "", "NO", "SI", "Falla en motor de arranque o solenoide defectuoso (clac seco o carbones gastados)", "L3 caída de tensión de 2.90V en prensado de cable negativo por corrosión.")
    agregar("G48-L3-10", CLASE_48, "L3", "Inspección de caja plástica de batería: fisura por fatiga de 4 cm en la base inferior del contenedor de polipropileno con fuga lenta de ácido sulfúrico hacia la bandeja de soporte; la densidad del vaso afectado cayó a 1.05 g/cm3 dejando la batería con solo 5 celdas operativas (10.2 V totales en circuito abierto).", "TALLER", "fisura_caja_polipropileno_fuga_acido", "fisura_contenedor_polipropileno|fuga_acido_sulfurico|5_celdas_operativas_10_2v", "falla_alternador", "", "NO", "SI", "Alternador defectuoso o placa de diodos quemada", "L3 fisura de caja con pérdida de electrolito deja 5 celdas en 10.2V.")
    agregar("G48-L3-11", CLASE_48, "L3", "Vehículo ingresa por reseteo continuo de dirección electroasistida EPS y código DTC C1551 de bajo voltaje de alimentación en la ECU de dirección: el escáner registra que durante el accionamiento del motor de arranque la tensión cae a 6.8 V durante 1.8 segundos; la batería original de fábrica tiene 6 años de antigüedad con resistencia óhmica cuatriplicada.", "TECNICO", "scanner_dtc_c1551_bajo_voltaje_cranking", "dtc_c1551_ecu_eps|tension_cae_a_6_8v_en_cranking|bateria_6_anos_resistencia_cuatriplicada", "falla_cremallera_eps", "C1551", "NO", "SI", "Cremallera de direccion asistida con holgura o fuga", "L3 DTC C1551 por caída a 6.8V en arranque debido a batería vieja.")
    agregar("G48-L3-12", CLASE_48, "L3", "Prueba de aceptación de carga (Charge Acceptance Test según norma EN 50342): tras descargar la batería al 50% y conectarla a fuente estabilizada de 14.40 V a 25°C la corriente absorbida es de apenas 1.4 A (especificación mínima superior a 12 A) por pasivación de sulfato de plomo en placas negativas.", "TECNICO", "charge_acceptance_en50342_1_4a_vs_12a", "aceptacion_carga_1_4a_vs_12a|pasivacion_sulfato_plomo|resistencia_a_recarga", "falla_alternador", "", "NO", "SI", "Alternador defectuoso o placa de diodos quemada", "L3 prueba EN 50342 acusa absorción de solo 1.4A por placas pasivadas.")
    agregar("G48-L3-13", CLASE_48, "L3", "Ensayo de arranque en frío a 0°C en cámara climática: la tensión de reposo marca 12.30 V pero al solicitar arranque a solenoide la tensión se desploma instantáneamente a 5.1 V bloqueando el Bendix en la corona; tras entibiar la batería a 25°C la tensión bajo carga asciende a 8.2 V confirmando pérdida crítica de capacidad CCA por sulfatación térmica previa.", "TECNICO", "camara_climatica_0c_desplome_5_1v", "camara_climatica_0c_desplome_5_1v|bendix_bloqueado|perdida_cca_por_frio", "falla_motor_arranque", "", "NO", "SI", "Falla en motor de arranque o solenoide defectuoso (clac seco o carbones gastados)", "L3 ensayo a 0°C desploma batería a 5.1V bloqueando bendix.")
    agregar("G48-L3-14", CLASE_48, "L3", "Comprobación de perno de apriete de borne positivo: perno de acero roscado barrido con torque nulo; al tirar del cable con la mano el borne se desprende del poste cónico de plomo; esto provocaba cortes de encendido aleatorios al pasar por resaltos de la calzada simulando fallo de sensor de cigüeñal.", "TALLER", "perno_rosca_barrida_borne_suelto", "perno_borne_positivo_barrido|borne_suelto_se_desprende|cortes_en_resaltos", "falla_sensor_ckp", "", "NO", "SI", "Falla en sensor de posicion de cigueñal (CKP) o arbol de levas (CMP)", "L3 borne positivo con rosca barrida causa cortes de encendido en baches.")
    agregar("G48-L3-15", CLASE_48, "L3", "Diagnóstico de batería EFB (Enhanced Flooded Battery) en vehículo Start-Stop: el sistema Start-Stop se encuentra desactivado permanentemente por la BCM con mensaje 'Gestión de Batería No Disponible'; el analizador de batería registra resistencia interna de 18.5 mohm y capacidad de 240 A CCA (original 720 A CCA) por sulfatación tras 85,000 ciclos de arranque urbano.", "TECNICO", "bateria_efb_start_stop_inactivo_240cca", "start_stop_desactivado_por_bcm|resistencia_18_5mohm|capacidad_240cca_vs_720cca", "falla_motor_arranque", "", "NO", "SI", "Falla en motor de arranque o solenoide defectuoso (clac seco o carbones gastados)", "L3 Start-Stop bloqueado por batería EFB degradada a 240 CCA.")

