    agregar("G49-L2-05", CLASE_49, "L2", "La barra de State of Charge (SOC) en el tablero pasa de 8 barras (lleno) a 2 barras (morado vacío) en apenas 500 metros de subida suave en vehículo híbrido.", "COTIDIANO", "subida_suave_500m_desplome_soc", "soc_desploma_8_a_2_barras_en_500m|perdida_capacidad_util", "falla_inversor", "", "NO", "SI", "Fallo en inversor de corriente IGBT o motor electrico (EV)", "L2 colapso del SOC de 8 a 2 barras en 500m confirma batería HV agotada.")
