    agregar("G49-L2-08", CLASE_49, "L2", "Vehículo eléctrico limita la potencia de propulsión al 40% al llegar al 30% de carga; dos celdas pouch de polímero de litio tienen hinchazón física y deforman el módulo.", "TALLER", "celdas_pouch_hinchadas", "potencia_limitada_al_40porciento|celdas_pouch_hinchadas_deformadas", "falla_motor_electrico", "", "NO", "SI", "Fallo en inversor de corriente IGBT o motor electrico (EV)", "L2 celdas pouch infladas limitan potencia al 40% descarta motor.")
    agregar("G49-L2-09", CLASE_49, "L2", "Al desacelerar en bajada el sistema de frenado regenerativo no acumula energía en la batería HV porque el BMS corta la carga por sobretensión en módulo 4.", "TECNICO", "frenado_regenerativo_corta_carga", "frenado_regenerativo_rechazado_por_bms|sobretension_modulo_4", "falla_freno_regenerativo", "", "NO", "SI", "Falla en sistema de frenado regenerativo (EV / Hibridos)", "L2 rechazo de carga regenerativa por módulo 4 defectuoso.")
    agregar("G49-L2-10", CLASE_49, "L2", "DTC P0A7E presente en módulo de batería de tracción referente a sobretemperatura física en celda de alta tensión sin existir obstrucción en el conducto de aire.", "TECNICO", "dtc_p0a7e_sobretemperatura_celda", "dtc_p0a7e|sobretemperatura_celda_hv|conductos_aire_limpios", "falla_ventilador_bateria", "P0A7E", "NO", "SI", "Foco o falla en sistema de refrigeracion de bateria/inversor (EV)", "L2 DTC P0A7E por celda degradada recalentada con ducto limpio.")
    agregar("G49-L2-11", CLASE_49, "L2", "Buenas tardes, el carro híbrido gasta el doble de gasolina porque la batería grande casi no aporta tracción; el modo 100% eléctrico se desconecta en 5 segundos.", "WHATSAPP", "modo_ev_desconecta_en_5s", "consumo_doble_gasolina|modo_ev_apaga_en_5_segundos|bateria_hv_sin_aporte", "falla_inyectores", "", "NO", "SI", "Inyectores sucios o filtro de combustible obstruido", "L2 modo EV de 5 segundos fuerza motor de gasolina elevando consumo.")
