    agregar("G49-L2-13", CLASE_49, "L2", "Batería de iones de litio de 400 V con State of Health de 58%; el vehículo completa la recarga del 20% al 80% en solo 12 minutos por pérdida severa de capacidad útil.", "TECNICO", "recarga_anormalmente_rapida_12min", "soh_58porciento_bateria_400v|recarga_20_a_80_en_12_minutos|perdida_capacidad_util", "falla_cargador_a_bordo", "", "NO", "NO", "", "L2 recarga anormalmente rápida por pérdida de capacidad útil en pack 400V.")
    agregar("G49-L2-14", CLASE_49, "L2", "Al conectar cargador de nivel 2 se interrumpe la carga al 65% con error de aislamiento interno en el módulo de celdas número 3 de la batería de tracción.", "TALLER", "cargador_nivel_2_interrumpe_65", "interrupcion_carga_al_65porciento|falla_aislamiento_modulo_3", "falla_inversor", "", "NO", "SI", "Fallo en inversor de corriente IGBT o motor electrico (EV)", "L2 interrupción de carga por fuga de aislamiento en módulo 3.")
    agregar("G49-L2-15", CLASE_49, "L2", "La aceleración en modo eléctrico trepida y se apaga de golpe si se pisa más de un tercio del acelerador; la batería HV no soporta demandas de corriente de más de 40 A.", "COTIDIANO", "aceleracion_modo_electrico_corte", "trepidacion_corte_al_acelerar_en_ev|bateria_hv_no_soporta_40a", "falla_motor_electrico", "", "NO", "SI", "Fallo en inversor de corriente IGBT o motor electrico (EV)", "L2 pack HV corta tracción por incapacidad de entregar 40A descarta motor.")

    # --- L3 (15 casos) ---
    agregar("G49-L3-01", CLASE_49, "L3", "Diagnóstico de batería de tracción NiMH de 201.6 V nominales (28 módulos de 7.2 V en serie) con software Techstream en vehículo híbrido: código de falla DTC P0A80 activo permanente. En prueba de esfuerzo en carretera bajo aceleración a plena carga en subida pronunciada el flujo de datos del BMS (Battery Smart Unit) revela un delta de tensión entre bloques (Delta Cell Block Voltage) de 1.85 V (bloque 6 cae a 13.12 V mientras el bloque 12 se mantiene en 14.97 V; especificación máxima tolerada menor a 0.25 V). La resistencia interna calculada del bloque 6 es de 0.052 ohmios (tres veces superior a la nominal). El ventilador de refrigeración opera sin obstrucciones a 3800 rpm descartando falla térmica.", "TECNICO", "techstream_p0a80_delta_bloques_1_85v", "dtc_p0a80|delta_bloques_1_85v_vs_0_25v|bloque_6_cae_a_13_12v|resistencia_0_052ohm|ventilador_ok", "falla_refrigeracion_bateria", "P0A80", "NO", "SI", "Foco o falla en sistema de refrigeracion de bateria/inversor (EV)", "L3 Techstream confirma P0A80 con delta de bloques de 1.85V y ventilador funcionando.")
    agregar("G49-L3-02", CLASE_49, "L3", "Evaluación de batería de iones de litio de 350 V (96 celdas prismáticas en serie) en vehículo eléctrico puro: State of Health (SOH) consolidado en 51.4% con capacidad útil restante de 18.2 kWh (capacidad nominal de fábrica 35.5 kWh). En ensayo de descarga en banco con carga activa a corriente constante de 1C (100 A) a 25°C tres de las celdas del módulo central colapsan por debajo del umbral de corte de seguridad de 2.75 V a los 9 minutos de prueba provocando apertura preventiva de los contactores pirotécnicos SMR. La batería auxiliar de 12 V se encuentra al 100% de carga (12.72 V) descartando fallo en red de baja tensión.", "TECNICO", "banco_descarga_1c_100a_soh_51_4porciento", "soh_51_4porciento_capacidad_18_2kwh|tres_celdas_colapsan_a_2_75v|apertura_smr|bateria_12v_ok", "falla_bateria_12v", "", "NO", "SI", "Bateria descargada o bornes sulfatados", "L3 banco de descarga 1C constata SOH en 51.4% con colapso de celdas a 2.75V.")
    agregar("G49-L3-03", CLASE_49, "L3", "Prueba de ciclado dinámico en banco con ciclador de alta tensión: paquete de batería híbrida presenta pérdida de capacidad coulombimétrica del 44% y resistencia interna de celda promedio de 38 miliohmios (nominal nueva 14 mohm). Durante el ensayo de recarga rápida a 50 kW la temperatura del núcleo de celdas se eleva a 52°C con solo 15 kW de potencia absorbida debido a disipación Joule por alta impedancia electroquímica interna, activando DTC P0A7F.", "TECNICO", "ciclador_banco_perdida_capacidad_44porciento", "dtc_p0a7f|perdida_capacidad_44porciento|resistencia_38mohm_vs_14mohm|temperatura_52c_a_15kw", "falla_refrigeracion_inversor", "P0A7F", "NO", "SI", "Foco o falla en sistema de refrigeracion de bateria/inversor (EV)", "L3 DTC P0A7F por pérdida del 44% de capacidad y resistencia interna de 38 mohm.")
    agregar("G49-L3-04", CLASE_49, "L3", "Hola maestro, tengo un Toyota Prius 2012. En la pantalla me salió el triángulo rojo y el mensaje de revisar sistema híbrido. En subida la barra de la batería se vacía en 20 segundos y el motor de gasolina ruge a 4000 rpm sin avanzar con fuerza. En el taller conectaron el escáner y el bloque de celdas número 11 tiene 12.1 V mientras los demás tienen 14.8 V; la batería de 12 V es nueva de gel y marca 12.8 V perfecta.", "WHATSAPP", "prius_triangulo_rojo_bloque_11_caido", "triangulo_rojo_revisar_hibrido|barra_bateria_vacia_20s|bloque_11_12_1v_vs_14_8v|bateria_12v_ok", "falla_bateria_12v", "", "NO", "SI", "Bateria descargada o bornes sulfatados", "L3 relato WhatsApp de Prius con bloque 11 en 12.1V vs 14.8V y batería 12V perfecta.")
    agregar("G49-L3-05", CLASE_49, "L3", "Medición de resistencia de aislamiento de pack de batería de tracción con megóhmetro de alta tensión Fluke a 1000 V DC: resistencia entre el terminal positivo de alta tensión (desconectado el disyuntor de servicio manual naranja) y la carcasa metálica de tierra chasis registra 0.12 Megaohmios (especificación mínima de seguridad según norma ISO 6469 debe superar 100 Megaohmios). La fuga de aislamiento proviene de electrolito alcalino de hidróxido de potasio fugado por la válvula de alivio de dos módulos NiMH corroídos.", "TECNICO", "megohmetro_fluke_1000v_aislamiento_0_12mohm", "aislamiento_0_12mohm_vs_100mohm_a_1000v|fuga_electrolito_koh_valvula_alivio|corrosion_modulos", "falla_aislamiento_inversor", "", "NO", "SI", "Fallo en inversor de corriente IGBT o motor electrico (EV)", "L3 megóhmetro a 1000V acusa 0.12 Mohm por fuga de electrolito en pack de tracción.")
    agregar("G49-L3-06", CLASE_49, "L3", "Diagnóstico de desequilibrio de celdas en vehículo híbrido enchufable PHEV: escáner registra DTC P0B3C (Hybrid Battery Voltage Sense Circuit Performance). En la gráfica de balanceo pasivo del BMS los circuitos equilibradores por resistencias shunt disipan energía de forma continua durante 6 horas sin lograr reducir la diferencia de tensión entre la celda 18 (3.42 V) y la celda 19 (4.15 V; delta de 730 mV) debido a microcortocircuito interno por dendritas de litio.", "TECNICO", "dtc_p0b3c_delta_730mv_dendritas", "dtc_p0b3c|delta_celdas_730mv|balanceo_pasivo_no_compensa|dendritas_litio_celda_18", "falla_inversor", "P0B3C", "NO", "SI", "Fallo en inversor de corriente IGBT o motor electrico (EV)", "L3 DTC P0B3C por delta de 730 mV entre celdas por dendritas de litio.")
    agregar("G49-L3-07", CLASE_49, "L3", "Mi carro electrico ase que la bateria baje del 80 porciento al 20 en menos de diez minutos de pista rapida. En el taller desarmaron la tapa del paquete de baterias y dos modulos tavan inchados con olor quimico penetrante y el escaner sacaba el codigo P0A80 de cambiar bateria grande. El motor electrico y el inversor no tienen ninguna falla.", "ERROR_ORTOGRAFICO", "descarga_80_a_20_modulos_hinchados", "descarga_80_a_20_en_10min|modulos_inchados_olor_quimico|dtc_p0a80|inversor_y_motor_ok", "falla_inversor_motor", "P0A80", "NO", "SI", "Fallo en inversor de corriente IGBT o motor electrico (EV)", "L3 módulos hinchados con P0A80 y descarte de inversor con ortografía informal.")
    agregar("G49-L3-08", CLASE_49, "L3", "Análisis de impedancia electroquímica (EIS) en módulo de batería LiFePO4: espectro de impedancia a frecuencias de 10 mHz a 10 kHz revela dispersión en el semicírculo de transferencia de carga con resistencia de polarización Rct incrementada en 450% respecto al valor canónico de fábrica, lo que impide al pack suministrar corrientes de aceleración superiores a 0.5C sin activar la protección BMS por subtensión transitoria.", "TECNICO", "espectroscopia_eis_rct_incrementada_450porciento", "espectro_eis_rct_incrementada_450porciento|polarizacion_electroquimica|corte_bms_a_0_5c", "falla_motor_traccion", "", "NO", "SI", "Fallo en inversor de corriente IGBT o motor electrico (EV)", "L3 espectroscopía EIS revela resistencia de transferencia de carga en +450%.")
    agregar("G49-L3-09", CLASE_49, "L3", "Evaluación de sensor de corriente de efecto Hall del paquete de batería HV (Battery Current Sensor): el escáner registra DTC P0A6B referente a circuito del sensor de corriente de batería de tracción; la lectura de corriente permanece fija en +18 A en reposo con contactores abiertos, provocando cálculo aberrante del State of Charge por integración de Coulomb en la ECU híbrida.", "TECNICO", "scanner_dtc_p0a6b_sensor_corriente_hall", "dtc_p0a6b|sensor_corriente_fijo_18a_en_reposo|calculo_soc_aberrante|contactores_abiertos", "falla_bateria_12v", "P0A6B", "NO", "SI", "Bateria descargada o bornes sulfatados", "L3 DTC P0A6B por sensor de corriente Hall de batería HV descalibrado.")
    agregar("G49-L3-10", CLASE_49, "L3", "Inspección de barra colectora de cobre (busbar) y tuercas de terminales de batería híbrida tras desmonte en entorno seguro con guantes dieléctricos Clase 0 (1000 V): corrosión galvánica severa de sulfato de cobre en 8 tuercas con resistencia de contacto de 0.85 ohmios en el puente entre módulo 14 y 15; esto induce una caída óhmica de 17.0 V al circular 20 A simulando caída de módulo en el BMS.", "TECNICO", "inspeccion_segura_busbars_corrosion_cobre", "resistencia_contacto_0_85ohm_busbar|caida_17_0v_a_20a|corrosion_galvanica_tuercas", "falla_cableado_12v", "", "NO", "SI", "Bateria descargada o bornes sulfatados", "L3 corrosión en busbars de pack HV induce 17V de caída de contacto.")
    agregar("G49-L3-11", CLASE_49, "L3", "Diagnóstico de fuga de tensión en bus de alta tensión con código DTC P0AA6 (Hybrid Battery Voltage System Isolation Fault) subcódigo INF 526: la unidad de detección de fugas (Leak Detection Circuit) mide una resistencia de aislamiento de 42 kOhm provocada por acumulación de humedad y polvo conductor sobre la bandeja portabaterías inferior sin que el inversor ni el motor presenten derivaciones.", "TECNICO", "dtc_p0aa6_inf_526_aislamiento_42kohm", "dtc_p0aa6_inf_526|aislamiento_42kohm|polvo_conductor_en_bandeja_pack|inversor_y_motor_ok", "falla_aislamiento_inversor", "P0AA6", "NO", "SI", "Fallo en inversor de corriente IGBT o motor electrico (EV)", "L3 DTC P0AA6 subcódigo 526 acusa 42 kOhm de aislamiento en pack HV.")
    agregar("G49-L3-12", CLASE_49, "L3", "Prueba de capacidad en descarga con analizador computarizado de 28 canales independientes en batería híbrida: 6 de los 28 módulos entregan una capacidad acumulada menor a 1800 mAh (especificación nominal 6500 mAh; pérdida de capacidad del 72%); los 22 módulos restantes promedian 4800 mAh, generando desbalance térmico y corte por baja tensión.", "TECNICO", "analizador_28_canales_capacidad_1800mah", "6_modulos_con_capacidad_1800mah_vs_6500mah|perdida_capacidad_72porciento|desbalance_termico", "falla_refrigeracion", "", "NO", "SI", "Foco o falla en sistema de refrigeracion de bateria/inversor (EV)", "L3 analizador de 28 canales constata 6 módulos con pérdida del 72% de capacidad.")
    agregar("G49-L3-13", CLASE_49, "L3", "Evaluación de módulo BMS esclavo (Cell Monitoring Unit / CMU) en batería de iones de litio de tracción: el circuito integrado de monitoreo multicanal presenta fallo en el convertidor analógico-digital (ADC) interno enviando lectura fija de 0.00 V en las celdas 33 a 40 con DTC P0B24; la verificación con multímetro de alta precisión en las celdas físicas constata 3.82 V reales y estables.", "TECNICO", "scanner_dtc_p0b24_falla_cmu_esclavo", "dtc_p0b24|cmu_envia_cero_voltios_celdas_33_a_40|multimetro_mide_3_82v_reales|falla_adc_bms", "falla_inversor", "P0B24", "NO", "SI", "Fallo en inversor de corriente IGBT o motor electrico (EV)", "L3 DTC P0B24 por fallo en ADC de placa CMU con celdas físicas sanas a 3.82V.")
    agregar("G49-L3-14", CLASE_49, "L3", "Prueba de esfuerzo con dinamómetro de chasis en vehículo EV: con 20% de SoC la aceleración máxima sostenida a 100 km/h provoca un colapso de tensión del pack completo de 380 V a 248 V (caída de 132 V) debido a degradación por envejecimiento de ciclo químico de las celdas, activando el modo de potencia reducida (icono de tortuga) a los 4 segundos.", "TECNICO", "dinamometro_colapso_tension_132v_tortuga", "pack_cae_380v_a_248v_caida_132v_a_20soc|modo_tortuga_a_los_4_segundos|envejecimiento_quimico", "falla_motor_electrico", "", "NO", "SI", "Fallo en inversor de corriente IGBT o motor electrico (EV)", "L3 dinamómetro acusa colapso de 132V a 20% SoC activando modo tortuga.")
    agregar("G49-L3-15", CLASE_49, "L3", "Sustitución de conjunto de batería de tracción tras fusión de fusible principal de servicio de 250 A / 450 V DC (Service Plug fuse): la apertura del fusible se produjo por sobrecorriente provocada por un cortocircuito interno entre electrodos positivos y negativos dentro del módulo 2 tras penetración de tornillo de fijación de accesorio no original.", "TALLER", "fusible_servicio_250a_fundido_corto_interno", "fusible_servicio_250a_450v_fundido|cortocircuito_interno_modulo_2|tornillo_perfora_modulo", "falla_inversor_igbt", "", "NO", "SI", "Fallo en inversor de corriente IGBT o motor electrico (EV)", "L3 fusible de servicio de 250A fundido por perforación y cortocircuito interno en módulo.")

